import React, { useState } from 'react';

// CSS 파일은 AdminPage.css를 사용한다고 했으니 별도의 import는 필요 없어!
// import './AccountInfoTab.css'; 

const AccountInfoTab = ({ adminInfo }) => {
  const [isEditing, setIsEditing] = useState(false);
  const [formData, setFormData] = useState({
    ...adminInfo,
    password: '',
    confirmPassword: '',
  });

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleDuplicateCheck = (field) => {
    // 실제 백엔드 중복 확인 API 호출 로직
    // 여기서는 예시로 성공 메시지를 띄우지만, 실제로는 API 호출 결과를 기반으로 해야 해!
    alert(`${formData[field]}은(는) 사용 가능합니다! ✅ (API 연동 필요)`);
    console.log(`${field} 중복 확인:`, formData[field]);
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    if (formData.password !== formData.confirmPassword) {
      alert('비밀번호와 비밀번호 확인이 일치하지 않아! 다시 확인해줘! 😵‍💫');
      return;
    }
    // 실제 백엔드 관리자 계정 정보 수정 API 호출 로직
    alert('관리자 계정 정보가 성공적으로 수정되었습니다! 🥳 (API 연동 필요)');
    console.log('수정된 관리자 정보:', formData);
    setIsEditing(false);
  };

  return (
    <div className="tab-content-section account-info-tab">
      <h3 className="tab-content-title">계정 정보 {!isEditing ? '보기' : '수정'}</h3>

      {!isEditing ? (
        <>
          <div className="info-item">
            <span className="info-label">아이디</span>
            <span className="info-value" style={{ textAlign: 'left', flexGrow: 1 }}>{userInfo.userId || '정보 없음'}</span> 
          </div>
          <div className="info-item">
            <span className="info-label">이메일</span>
            <span className="info-value" style={{ textAlign: 'left', flexGrow: 1 }}>{userInfo.email || '정보 없음'}</span>
          </div>
          <div className="info-item">
            <span className="info-label">닉네임</span>
            <span className="info-value" style={{ textAlign: 'left', flexGrow: 1 }}>{userInfo.nickname || '정보 없음'}</span> 
          </div>
          <div className="info-item">
            <span className="info-label">가입일</span>
            <span className="info-value" style={{ textAlign: 'left', flexGrow: 1 }}>{userInfo.registeredDate || '정보 없음'}</span>
          </div>
          <button className="action-button" onClick={() => setIsEditing(true)}>정보 수정 ✏️</button>
        </>
      ) : (
        <form onSubmit={handleSubmit}>
          {/* 이메일 수정 필드 */}
          <div className="info-item action-input-group">
            <label className="info-label" htmlFor="email">이메일</label>
            <div className="input-with-button">
              <input
                type="email"
                id="email"
                name="email"
                value={formData.email}
                onChange={handleChange}
                className="info-value-input"
                required 
              />
              <button type="button" className="check-button" onClick={handleCheckEmailDuplication}>중복 확인</button>
            </div>
          </div>
          
          {/* 닉네임 수정 필드 */}
          <div className="info-item action-input-group">
            <label className="info-label" htmlFor="nickname">닉네임</label>
            <div className="input-with-button">
              <input
                type="text"
                id="nickname"
                name="nickname"
                value={formData.nickname}
                onChange={handleChange}
                className="info-value-input"
                required 
              />
              <button type="button" className="check-button" onClick={handleCheckNicknameDuplication}>중복 확인</button>
            </div>
          </div>

          {/* 비밀번호 변경 필드 */}
          <div className="info-item action-input-group">
            <label className="info-label" htmlFor="password">새 비밀번호</label>
            <div className="input-with-button">
              <input
                type="password"
                id="password"
                name="password"
                value={formData.password}
                onChange={handleChange}
                className="info-value-input"
                placeholder="변경하실 비밀번호를 입력해주세요."
                autoComplete="new-password" 
              />
            </div>
          </div>
          <div className="info-item action-input-group">
            <label className="info-label" htmlFor="confirmPassword">새 비밀번호 확인</label>
            <div className="input-with-button">
              <input
                type="password"
                id="confirmPassword"
                name="confirmPassword"
                value={formData.confirmPassword}
                onChange={handleChange}
                className="info-value-input"
                placeholder="비밀번호를 다시 한번 입력해주세요."
                autoComplete="new-password" 
              />
            </div>
          </div>
          
          <div className="button-group" style={{ display: 'flex', justifyContent: 'flex-end', gap: '10px', marginTop: '30px' }}>
            <button type="submit" className="action-button">저장 ✅</button>
            <button type="button" className="action-button" onClick={() => setIsEditing(false)}>취소 ↩️</button>
            <button type="button" className="action-button delete-button" onClick={handleWithdrawal}>회원 탈퇴 🗑️</button>
          </div>
        </form>
      )}
    </div>
  );
};

export default AccountInfoTab;
